from pathlib import Path
import glob, os, re, subprocess, hashlib, time
SHA="2141d6f41816f70997df42b54bcc85b2c72a92c8"
apk=Path("app/build/outputs/apk/debug/app-debug.apk")
reference=Path("build/adb-install")/SHA/"phone-installed-base.apk"
if not apk.is_file() or not reference.is_file():
    raise SystemExit("SIGNATURE_REFERENCE_OR_NEW_APK_MISSING")
sdk=[]
for root in (os.environ.get("ANDROID_HOME"),os.environ.get("ANDROID_SDK_ROOT"),str(Path.home()/"Library/Android/sdk")):
    if root: sdk+=glob.glob(str(Path(root)/"build-tools"/"*"/"apksigner"))
if not sdk: raise SystemExit("APKSIGNER_MISSING")
signer=sorted(sdk)[-1]
def run(args,timeout=90):
    return subprocess.run(args,capture_output=True,text=True,timeout=timeout)
def cert(path):
    r=run([signer,"verify","--print-certs",str(path)])
    if r.returncode: raise SystemExit("APK_SIGNATURE_VERIFY_FAILED")
    m=re.search(r"Signer #1 certificate SHA-256 digest:\s*([0-9a-fA-F:]+)",r.stdout)
    if not m: raise SystemExit("APK_SIGNATURE_MISSING")
    return m.group(1).lower().replace(":","")
matching=cert(apk)==cert(reference)
print("LOCAL_BUILD_SIGNER_MATCHES_EXISTING_APP",matching)
if not matching: raise SystemExit("SIGNATURE_MISMATCH_NO_INSTALL_OR_DATA_RESET")
p=run(["adb","devices","-l"])
usb=[]
for line in p.stdout.splitlines()[1:]:
    fields=line.split()
    if len(fields)>=2 and fields[1]=="device" and ("usb:" in line or (":" not in fields[0] and not fields[0].startswith("emulator-"))):
        usb.append(fields[0])
print("AUTHORIZED_USB_COUNT",len(usb))
if len(usb)!=1:raise SystemExit("USB_DEVICE_UNAVAILABLE")
serial=usb[0]
def shell(*parts):
    r=run(["adb","-s",serial,"shell",*parts])
    if r.returncode: raise SystemExit("ADB_SHELL_FAILED")
    return r.stdout.strip()
if shell("getprop","ro.product.model")!="SM-S906B":raise SystemExit("WRONG_DEVICE_MODEL")
print("TARGET_MODEL","SM-S906B")
print("INSTALL_MODE","adb install -r, data preserved")
r=run(["adb","-s",serial,"install","-r",str(apk.resolve())],timeout=300)
message=(r.stdout+" "+r.stderr).strip()
if r.returncode or "Success" not in message:
    print("INSTALL_FAILED",message.splitlines()[-1][:400] if message else "no output")
    raise SystemExit("ADB_INSTALL_FAILED_NO_UNINSTALL")
print("ADB_INSTALL_SUCCESS",True)
if not shell("pm","path","io.blueeye").startswith("package:"):
    raise SystemExit("PACKAGE_NOT_PRESENT_AFTER_INSTALL")
print("PACKAGE_INSTALLED",True)
launch=run(["adb","-s",serial,"shell","am","start","-a","android.intent.action.MAIN","-c","android.intent.category.LAUNCHER","-p","io.blueeye"],timeout=45)
print("LAUNCH_COMMAND_OK",launch.returncode==0 and "Error" not in (launch.stdout+launch.stderr))
time.sleep(4)
proc=run(["adb","-s",serial,"shell","pidof","io.blueeye"])
print("APP_PROCESS_RUNNING",proc.returncode==0 and bool(proc.stdout.strip()))
print("APK_SHA256",hashlib.sha256(apk.read_bytes()).hexdigest())
print("EXACT_SOURCE_SHA",SHA)
if launch.returncode or "Error" in (launch.stdout+launch.stderr) or proc.returncode!=0 or not proc.stdout.strip():
    raise SystemExit("INSTALLED_BUT_LAUNCH_CHECK_FAILED")
print("USB_INSTALL_AND_LAUNCH_PASS")
PY
